import java.time.LocalDateTime;

public class ShiftOverlapCalculatorTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static LocalDateTime at(String text) {
        return LocalDateTime.parse(text);
    }

    static Object overlap(String startA, String endA, String startB, String endB) {
        try {
            return ShiftOverlapCalculator.overlapMinutes(at(startA), at(endA), at(startB), at(endB));
        } catch (Throwable crash) {
            return "overlapMinutes threw " + crash.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("a plain Monday overlap", 90L,
                overlap("2024-05-06T08:00", "2024-05-06T12:00", "2024-05-06T10:30", "2024-05-06T18:00"));
        check("time outside 09:00-17:00 does not count", 480L,
                overlap("2024-05-06T00:00", "2024-05-07T00:00", "2024-05-06T00:00", "2024-05-07T00:00"));
        check("intervals that only touch share nothing", 0L,
                overlap("2024-05-06T09:00", "2024-05-06T12:00", "2024-05-06T12:00", "2024-05-06T16:00"));
        check("no overlap at all", 0L,
                overlap("2024-05-06T09:00", "2024-05-06T10:00", "2024-05-06T14:00", "2024-05-06T15:00"));
        check("a weekend gap is skipped", 960L,
                overlap("2024-05-03T00:00", "2024-05-07T00:00", "2024-05-03T00:00", "2024-05-07T00:00"));
        check("a backwards interval counts as nothing", 0L,
                overlap("2024-05-06T12:00", "2024-05-06T09:00", "2024-05-06T09:00", "2024-05-06T17:00"));
        check("an evening-only overlap is outside working hours", 0L,
                overlap("2024-05-06T17:00", "2024-05-06T23:00", "2024-05-06T18:00", "2024-05-06T22:00"));
        check("a shift running past midnight into Tuesday", 120L,
                overlap("2024-05-06T15:30", "2024-05-07T10:00", "2024-05-06T16:00", "2024-05-07T23:00"));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

