/**
 * TASK: Measure how much two shifts overlap DURING working hours.
 *
 * overlapMinutes(startA, endA, startB, endB) returns how many minutes the two
 * half-open intervals [start, end) share, counting only minutes that fall on a
 * weekday (Monday to Friday) between 09:00 (inclusive) and 17:00 (exclusive).
 *
 * The intervals may run over several days. Intervals that merely touch at an
 * endpoint share nothing. If either interval is empty or backwards (end not
 * after start) the answer is 0.
 *
 * Example: A = 2024-05-06T08:00 to 2024-05-06T12:00 (a Monday)
 *          B = 2024-05-06T10:30 to 2024-05-06T18:00
 *          the raw overlap is 10:30-12:00 = 90 minutes, all of it inside
 *          working hours, so the answer is 90.
 *
 * Plan: intersect the two intervals first, then walk the intersection one
 * calendar day at a time and clip each day to its 09:00-17:00 window.
 */
import java.time.DayOfWeek;
import java.time.Duration;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.time.LocalTime;

public class ShiftOverlapCalculator {

    private static final LocalTime OPEN = LocalTime.of(9, 0);
    private static final LocalTime CLOSE = LocalTime.of(17, 0);

    public static long overlapMinutes(LocalDateTime startA, LocalDateTime endA,
                                      LocalDateTime startB, LocalDateTime endB) {
        if (!endA.isAfter(startA) || !endB.isAfter(startB)) {
            return 0L;
        }
        LocalDateTime start = startA.isAfter(startB) ? startA : startB;
        LocalDateTime end = endA.isBefore(endB) ? endA : endB;
        if (!end.isAfter(start)) {
            return 0L;
        }

        long minutes = 0L;
        LocalDate day = start.toLocalDate();
        while (!day.isAfter(end.toLocalDate())) {
            if (isWeekday(day)) {
                LocalDateTime open = LocalDateTime.of(day, OPEN);
                LocalDateTime close = LocalDateTime.of(day, CLOSE);
                LocalDateTime from = start.isAfter(open) ? start : open;
                LocalDateTime to = end.isBefore(close) ? end : close;
                if (to.isAfter(from)) {
                    minutes += Duration.between(from, to).toMinutes();
                }
            }
            day = day.plusDays(1);
        }
        return minutes;
    }

    private static boolean isWeekday(LocalDate day) {
        DayOfWeek dow = day.getDayOfWeek();
        return dow != DayOfWeek.SATURDAY && dow != DayOfWeek.SUNDAY;
    }
}
